  "candidates": [
    {
      "id": "cycle_decomposition",
      "title": "A linear cycle-and-edge decomposition of every graph",
      "paper_id": "../preprints/A-linear-cycle-and-edge-decomposition-of-every-graph-September-24-2026/main.pdf",
      "paper_url": "https://github.com/openai/math/blob/fd4aeeb2ee4fc729c18d98444fed42fd0529eeeb/preprints/A-linear-cycle-and-edge-decomposition-of-every-graph-September-24-2026/main.pdf",
      "scope_doc": "https://github.com/openai/math/blob/fd4aeeb2ee4fc729c18d98444fed42fd0529eeeb/lean/docs/181.md",
      "main_result": "There is an absolute constant C > 0 such that every finite simple graph on n vertices has an edge-disjoint partition into cycles and single edges using at most C n pieces. The formalized statement includes edgeless and small graphs; it does not determine the optimal C.",
      "theorem": "OAI.ErdosGallai.erdos_gallai",
      "challenge_module": "ComparatorChallenges.CycleDecomposition",
      "solution_module": "OAI.Combinatorics.CycleDecomposition.Main",
      "challenge_spec": "lean/ComparatorChallenges/CycleDecomposition.lean",
      "challenge_config": "lean/ComparatorChallenges/CycleDecomposition.json",
      "definition_names": [],
      "permitted_axioms": [
        "propext",
        "Quot.sound",
        "Classical.choice"
      ],
