    },
    {
      "id": "seymour_second_neighborhood",
      "title": "A proof of Seymour’s second-neighborhood conjecture",
      "paper_id": "../preprints/A-proof-of-Seymours-second-neighborhood-conjecture-September-23-2026/paper.pdf",
      "paper_url": "https://github.com/openai/math/blob/fd4aeeb2ee4fc729c18d98444fed42fd0529eeeb/preprints/A-proof-of-Seymours-second-neighborhood-conjecture-September-23-2026/paper.pdf",
      "scope_doc": "https://github.com/openai/math/blob/fd4aeeb2ee4fc729c18d98444fed42fd0529eeeb/lean/docs/173.md",
      "main_result": "Every nonempty finite oriented graph has a vertex whose number of out-neighbors at directed distance exactly two is at least its outdegree. The scope excludes the starting vertex and first out-neighbors from the second neighborhood, and includes sinks.",
      "theorem": "OAI.SeymourSecondNeighborhood.exists_goodVertex",
      "challenge_module": "ComparatorChallenges.SeymourSecondNeighborhood",
      "solution_module": "OAI.Combinatorics.SecondNeighborhood.Main",
