    {
      "id": "borsuk_nine",
      "title": "A nine-dimensional counterexample to Borsuk’s covering assertion",
      "paper_id": "../preprints/A-nine-dimensional-counterexample-to-Borsuks-covering-assertion-September-23-2026/paper.pdf",
      "paper_url": "https://github.com/openai/math/blob/fd4aeeb2ee4fc729c18d98444fed42fd0529eeeb/preprints/A-nine-dimensional-counterexample-to-Borsuks-covering-assertion-September-23-2026/paper.pdf",
      "scope_doc": "https://github.com/openai/math/blob/fd4aeeb2ee4fc729c18d98444fed42fd0529eeeb/lean/docs/156.md",
      "main_result": "The main comparator target states that the compact set of rank-one orthogonal projectors onto lines in R^4 lies in the trace-one symmetric matrix space, has diameter sqrt(2), and cannot be covered by ten arbitrary subsets of strictly smaller diameter. The solution module separately derives an isometric image in R^9 giving the nine-dimensional Euclidean counterexample; that corollary is not among this comparator’s named theorem targets.",
